function memoryConnector(exporter: MemoryLogExporter, closed: { n: number }): LogConnector {
  return ({ resource, onDropped }) => {
    const logs = new BatchingLogClient(exporter, {
      resource,
      batch: { flushIntervalMs: 60_000, onDrop: onDropped },
    });
    return {
      logs,
      close: async () => {
        closed.n++;
        await logs.close();
      },
    };
  };
}

