class FakeResponse extends EventEmitter {
  statusCode = 200;
  headers: Record<string, string> = {};
  setHeader(name: string, value: string): void {
    this.headers[name] = value;
  }
}

describe("requestLogger", () => {
  it("sets the request id and logs completion by status", () => {
    const lines: string[] = [];
    initLogging({ env: {}, level: "debug", write: (l) => lines.push(l) });
    const mw = requestLogger();
    for (const [status, level] of [
      [200, "info"],
      [404, "warn"],
      [503, "error"],
    ] as const) {
      const res = new FakeResponse();
      let inside: string | undefined;
      mw({ method: "POST", url: "/orders?x=1", headers: { "x-request-id": "abc" } }, res, () => {
        inside = currentRequestId();
      });
      expect(inside).toBe("abc");
      expect(res.headers["x-request-id"]).toBe("abc");
      res.statusCode = status;
      res.emit("finish");
      res.emit("close");
      expect(JSON.parse(lines.at(-1) ?? "{}")).toMatchObject({
        level,
        msg: "request completed",
        request_id: "abc",
        "http.route": "/orders",
        "http.status_code": status,
      });
    }
    expect(lines).toHaveLength(3);
  });

  it("creates ids, skips health paths and accepts a custom logger", () => {
    const sent: string[] = [];
    const logger = {
      info: (m: string) => sent.push(m),
      warn: (m: string) => sent.push(m),
      error: (m: string) => sent.push(m),
    } as unknown as Parameters<typeof requestLogger>[0] extends infer O
      ? O extends { logger?: infer L }
        ? L
        : never
      : never;
    const mw = requestLogger({ logger, header: "X-Trace", skip: ["/health"] });
    const res = new FakeResponse();
    mw({ headers: { "x-trace": ["  "] }, originalUrl: "/health/check" }, res, () => undefined);
    res.emit("finish");
    expect(res.headers["x-trace"]).toMatch(/^[0-9a-f-]{36}$/);
    expect(sent).toEqual([]);
    const res2 = new FakeResponse();
    mw({ headers: {} }, res2, () => undefined);
    res2.emit("finish");
    expect(sent).toEqual(["request completed"]);
  });
});
